from enum import Enum
from fastapi import FastAPI

class ModelName(str, Enum):
    alexnet = "alexnet"
    resnet = "resnet"

app = FastAPI()

@app.get("/models/{model_name}")
async def read_model(model_name: ModelName) -> dict[str, str]:
    return {"model_name": model_name.value}

from fastapi import FastAPI
from pydantic import BaseModel

class Item(BaseModel):
    name: str
    price: float

app = FastAPI()

@app.post("/items")
async def create_item(item: Item) -> dict[str, object]:
    return item.model_dump()

from typing import Annotated
from fastapi import Body, FastAPI
from pydantic import BaseModel

class Item(BaseModel):
    name: str

class User(BaseModel):
    username: str

app = FastAPI()

@app.put("/items/{item_id}")
async def update_item(item_id: int, item: Item, user: User, importance: Annotated[int, Body(gt=0)]) -> dict[str, object]:
    return {"item_id": item_id, "item": item, "user": user, "importance": importance}
